// swift-tools-version:5.9
//
// The Swift half of leaf-mermaid-ffi: `renderMermaid`, for the app's
// `fence:mermaid` renderer. Not part of leaf's Swift package — leaf draws no
// diagrams — but the app's own, as the Rust half is leaf-ffi's `mermaid`
// feature, which the app's pre-build step turns on (see ../project.yml).
//
// Both inputs are generated by scripts/gen-bindings.sh and held to
// crates/leaf-mermaid-ffi by CI (`--check`): the C module under `headers/` and
// the Swift over it under `Sources/LeafMermaidFFI/`. The symbols are in the
// leaf-ffi archive the app force-loads, as `LeafFFI`'s are.
import PackageDescription

let package = Package(
    name: "LeafMermaid",
    platforms: [.macOS(.v13), .iOS(.v16)],
    products: [
        .library(name: "LeafMermaidFFI", targets: ["LeafMermaidFFI"]),
    ],
    targets: [
        .systemLibrary(name: "leaf_mermaid_ffiFFI", path: "headers"),
        .target(name: "LeafMermaidFFI", dependencies: ["leaf_mermaid_ffiFFI"],
                path: "Sources/LeafMermaidFFI"),
    ]
)
